import Testing
import Foundation
import TailoringModel

/// A corpus of inputs and what cv-giovanni's `fold` returns for each, so every platform checks the same thing: the folding
/// of the Unicode data of the toolchain it is built with, against the folding of the source. It is generated by
/// `CVTailoring/Tools/GenerateFoldCorpus.mjs` with a fixed seed, and holds the classes of text that fold treats in their own
/// way: diacritics, ß and ẞ, ligatures, compatibility forms, combining marks, the white space the source reads and the
/// one it does not, sigma at the end of a word, and scripts that do not decompose.
@Suite("TextFold · the corpus of the source's outputs (#136)")
struct FoldCorpusTests {
    private func corpus() throws -> [[String]] {
        let url = try #require(Bundle.module.url(forResource: "Resources/FoldCorpus", withExtension: "json"))
        return try JSONDecoder().decode([[String]].self, from: Data(contentsOf: url))
    }

    @Test("the corpus holds about two thousand pairs, each a text and its fold")
    func shape() throws {
        let pairs = try corpus()
        #expect(pairs.count >= 2000)
        #expect(pairs.allSatisfy { $0.count == 2 })
    }

    @Test("TextFold returns what the source returns for every text of the corpus")
    func everyPair() throws {
        var mismatches = 0
        for pair in try corpus() where TextFold.fold(pair[0]) != pair[1] {
            mismatches += 1
            if mismatches <= 5 {
                Issue.record("fold of \(pair[0].unicodeScalars.map { String($0.value, radix: 16) }) is \(TextFold.fold(pair[0]).unicodeScalars.map { String($0.value, radix: 16) }), the source gives \(pair[1].unicodeScalars.map { String($0.value, radix: 16) })")
            }
        }
        #expect(mismatches == 0)
    }

    @Test("the corpus covers each class of text that fold treats in its own way")
    func classes() throws {
        let texts = try corpus().map { $0[0] }
        func holds(_ predicate: (Unicode.Scalar) -> Bool) -> Bool { texts.contains { $0.unicodeScalars.contains(where: predicate) } }
        #expect(holds { $0 == "\u{00DF}" } && holds { $0 == "\u{1E9E}" })
        #expect(holds { (0xFB00...0xFB06).contains($0.value) } && holds { $0 == "\u{0133}" })
        #expect(holds { (0x0300...0x036F).contains($0.value) } && holds { $0 == "\u{20D0}" })
        #expect(holds { $0 == "\u{03A3}" } && holds { $0 == "\u{03C2}" })
        #expect(holds { $0 == "\u{0130}" } && holds { $0 == "\u{0131}" })
        #expect(holds { $0 == "\u{00A0}" } && holds { $0 == "\u{3000}" } && holds { $0 == "\u{FEFF}" } && holds { $0 == "\u{2028}" })
        #expect(holds { $0 == "\u{0085}" } && holds { $0 == "\u{180E}" } && holds { $0 == "\u{200B}" })
        #expect(holds { $0.value >= 0x1F300 } && holds { (0x0400...0x04FF).contains($0.value) } && holds { (0xAC00...0xD7A3).contains($0.value) })
    }
}
